code.snippet:
body.t-matrix .hero h1 { text-shadow: 0 0 14px rgba(0,255,65,.75), 0 0 42px rgba(0,255,65,.4); letter-spacing: 4px; }
body.t-matrix .tagline { text-shadow: 0 0 10px rgba(0,255,65,.6); }
body.t-matrix .tagline::before { content: "> "; color: var(--text-2); }
body.t-matrix .section-title { text-shadow: 0 0 12px rgba(0,255,65,.5); text-transform: uppercase; letter-spacing: 2px; }
body.t-matrix .section-tag { background: rgba(0,255,65,.08); letter-spacing: 3px; }
body.t-matrix .card:hover { box-shadow: 0 0 24px rgba(0,255,65,.2), inset 0 0 18px rgba(0,255,65,.05); }
body.t-matrix .card.featured { border-color: var(--accent); }
body.t-matrix .card.featured::before { content: "★ THE ONE"; background: var(--accent); color: #000; border-radius: 0; }
body.t-matrix .btn { letter-spacing: 1px; }
body.t-matrix .btn-primary { background: var(--accent); color: #000; font-weight: 700; }
body.t-matrix .btn-primary:hover { box-shadow: 0 0 30px rgba(0,255,65,.5); }
body.t-matrix .btn-ghost:hover { box-shadow: 0 0 16px rgba(0,255,65,.25); }
body.t-matrix .bar-track { border: 1px solid rgba(0,255,65,.25); background: transparent; height: 12px; }
body.t-matrix .bar-fill { background: repeating-linear-gradient(90deg, var(--accent) 0 4px, transparent 4px 6px); }
body.t-matrix .hero-badge i { border-radius: 0; animation: matrixblink 1s steps(2) infinite; }
@keyframes matrixblink { 50% { opacity: .1; box-shadow: none; } }
body.t-matrix .stat b { text-shadow: 0 0 10px rgba(0,255,65,.6); }
body.t-matrix .logo::after { content: "_"; color: var(--accent); animation: matrixblink 1s steps(2) infinite; }
